/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_family_children_ai

AFTER INSERT ON family_children

FOR EACH ROW

BEGIN

    UPDATE families

    SET children_count = (

        SELECT COUNT(*)

        FROM family_children

        WHERE family_id = NEW.family_id

    )

    WHERE id = NEW.family_id;

END */;;
