/*!50003 CREATE*/ /*!50017 DEFINER=`root`@`localhost`*/ /*!50003 TRIGGER trg_family_children_au

AFTER UPDATE ON family_children

FOR EACH ROW

BEGIN

    IF OLD.family_id <> NEW.family_id THEN

        UPDATE families

        SET children_count = (

            SELECT COUNT(*)

            FROM family_children

            WHERE family_id = OLD.family_id

        )

        WHERE id = OLD.family_id;

    END IF;



    UPDATE families

    SET children_count = (

        SELECT COUNT(*)

        FROM family_children

        WHERE family_id = NEW.family_id

    )

    WHERE id = NEW.family_id;

END */;;
